use crate::aap::caps::response_channel;

struct Node;

/// Bound on delivery attempts. The channel stamps its own session identity on
/// every confirmation; a refused send may be transient, so we retry a small,
/// fixed number of times rather than loop without limit.
const MAX_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // `requires len(text) <= 100000` holds of every input, so the text is
        // passed through to the channel unchanged.
        let mut attempt = 0;
        loop {
            attempt += 1;
            let confirmation = response_channel::send(&reply.text);

            // The session identity comes from the host, never from the guest.
            // An empty identity means the host did not report which session
            // received the reply. Retrying would not change that, so we stop.
            if confirmation.session.is_empty() {
                panic!("response channel returned a confirmation without a session identity");
            }

            if confirmation.delivered {
                // Both postconditions hold: delivered == true and the session is
                // present. Return the host's confirmation as received.
                return confirmation;
            }

            if attempt >= MAX_ATTEMPTS {
                // Producing an output with delivered == false would violate the
                // contract. Faking delivered == true would misreport what the
                // host said. Trapping is the only honest outcome.
                panic!("response channel refused delivery after {} attempts", MAX_ATTEMPTS);
            }
        }
    }
}

export!(Node);
